        @app.route('/api/base_stations/bulk_delete', methods=['POST'])
        @login_required
        def api_bulk_delete_base_stations():
            """Delete multiple base stations at once (Improvement #12).

            Skips stations that still have mountpoints (same guard as single
            delete) and reports per-station outcomes so the UI can show a
            precise summary rather than an all-or-nothing result.
            """
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                data = request.json or {}
                ids = data.get('ids')
                if not isinstance(ids, list) or not ids:
                    return jsonify({'error': 'Provide a non-empty list of station ids'}), 400

                # Normalise + de-dup
                try:
                    id_list = sorted({int(x) for x in ids})
                except (TypeError, ValueError):
                    return jsonify({'error': 'ids must be integers'}), 400

                if len(id_list) > 200:
                    return jsonify({'error': 'Too many stations in one request (max 200)'}), 400

                deleted = []
                skipped = []
                for sid in id_list:
                    station = BaseStation.query.get(sid)
                    if not station:
                        skipped.append({'id': sid, 'reason': 'Not found'})
                        continue
                    if MountPoint.query.filter_by(base_id=sid).first():
                        skipped.append({'id': sid, 'name': station.name, 'reason': 'Has mountpoints'})
                        continue
                    db.session.delete(station)
                    deleted.append({'id': sid, 'name': station.name})

                db.session.commit()
                return jsonify({
                    'message': f'Deleted {len(deleted)} station(s), skipped {len(skipped)}',
                    'deleted': deleted,
                    'skipped': skipped,
                }), 200
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error in bulk delete base stations: {e}")
                return jsonify({'error': str(e)}), 500
        
