        @app.route('/api/rovers/create', methods=['POST'])
        @login_required
        def api_create_rover():
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                data = request.json
                if not data or 'username' not in data or 'password' not in data:
                    return jsonify({'error': 'Missing required fields'}), 400

                rover_username = str(data.get('username', '')).strip()
                rover_password = str(data.get('password', ''))
                if len(rover_username) < 3 or len(rover_username) > 32:
                    return jsonify({'error': 'Rover username must be between 3 and 32 characters'}), 400

                _validate_password_strength(
                    rover_password,
                    username=rover_username,
                    min_length=ROVER_PASSWORD_MIN_LENGTH,
                    label='Rover password'
                )
                
                # Check if rover already exists
                existing = Rover.query.filter_by(username=rover_username).first()
                if existing:
                    return jsonify({'error': 'Rover with this username already exists'}), 400
                
                # Hash password
                hashed_password = bcrypt.generate_password_hash(rover_password).decode()
                
                # Process mountpoints
                mountpoints = ''
                if 'mountpoints' in data and data['mountpoints']:
                    if isinstance(data['mountpoints'], list):
                        mountpoints = ','.join(data['mountpoints'])
                    else:
                        mountpoints = data['mountpoints']
                
                rover = Rover(
                    username=rover_username,
                    password=hashed_password,
                    email=data.get('email', ''),
                    mountpoints=mountpoints,
                    max_conn=data.get('max_conn', 1),
                    expires=data.get('expires', 0),
                    is_active=data.get('is_active', True)
                )
                
                db.session.add(rover)
                db.session.commit()
                return jsonify({'message': 'Rover created', 'id': rover.id}), 201
            except ValueError as e:
                db.session.rollback()
                return jsonify({'error': str(e)}), 400
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error creating rover: {e}")
                return jsonify({'error': str(e)}), 500
        
