        def _csv_safe(value):
            """Neutralise CSV/formula injection.

            A leading =, +, -, @, tab or CR can be interpreted as a formula by
            spreadsheet apps. Prefix such values with a single quote so they are
            treated as text (OWASP CSV injection guidance).
            """
            s = '' if value is None else str(value)
            if s and s[0] in ('=', '+', '-', '@', '\t', '\r'):
                return "'" + s
            return s

        def _stream_csv(header, rows, filename):
            """Build a downloadable CSV Response from header + row iterables."""
            buf = io.StringIO()
            writer = csv.writer(buf, quoting=csv.QUOTE_MINIMAL)
            writer.writerow(header)
            for row in rows:
                writer.writerow([_csv_safe(c) for c in row])
            output = buf.getvalue()
            buf.close()
            return Response(
                output,
                mimetype='text/csv',
                headers={
                    'Content-Disposition': f'attachment; filename="{filename}"',
                    'Cache-Control': 'no-store',
                },
            )

        @app.route('/api/logs/export')
        @login_required
        def api_logs_export():
            """Export filtered system logs as CSV (Improvement #11)."""
            try:
                limit = min(int(request.args.get('limit', 1000)), 10000)
                level = request.args.get('level')
                module = request.args.get('module')

                query = LogEntry.query.order_by(LogEntry.timestamp.desc())
                if level:
                    query = query.filter_by(level=level)
                if module:
                    query = query.filter_by(module=module)
                logs = query.limit(limit).all()

                def _rows():
                    for log in logs:
                        ts_iso = datetime.fromtimestamp(
                            int(log.timestamp or 0), tz=timezone.utc
                        ).isoformat() if log.timestamp else ''
                        yield [
                            log.id, ts_iso, log.level, log.module,
                            log.message, log.ip_address,
                        ]

                stamp = datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')
                return _stream_csv(
                    ['id', 'timestamp_utc', 'level', 'module', 'message', 'ip_address'],
                    _rows(),
                    f'gnss-caster-logs_{stamp}.csv',
                )
            except Exception as e:
                logger.error(f"Error exporting logs CSV: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/base_stations/<int:id>/command_log/export')
        @login_required
        def api_command_log_export(id):
            """Export a station's receiver command history as CSV (Improvement #11)."""
            try:
                from app.db.models import CommandLog
                station = BaseStation.query.get_or_404(id)
                limit = min(int(request.args.get('limit', 1000)), 10000)
                phase = request.args.get('phase')

                query = (
                    CommandLog.query
                    .filter_by(station_id=station.id)
                    .order_by(CommandLog.ts.desc())
                )
                if phase:
                    query = query.filter(CommandLog.phase.like(f'{phase}%'))
                entries = query.limit(limit).all()

                def _rows():
                    for e in entries:
                        ts_iso = datetime.fromtimestamp(
                            int(e.ts or 0), tz=timezone.utc
                        ).isoformat() if e.ts else ''
                        yield [e.id, ts_iso, e.phase, e.command, e.response]

                safe_name = re.sub(r'[^A-Za-z0-9_-]+', '_', str(station.name or f'station{id}'))
                stamp = datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')
                return _stream_csv(
                    ['id', 'timestamp_utc', 'phase', 'command', 'response'],
                    _rows(),
                    f'gnss-caster-commands_{safe_name}_{stamp}.csv',
                )
            except Exception as e:
                logger.error(f"Error exporting command log CSV: {e}")
                return jsonify({'error': str(e)}), 500
        
        @app.route('/api/system/settings')
        @login_required
        def api_system_settings():
            try:
                # Secrets are never echoed back. The UI only needs to know
                # whether one is stored, and any read-only account with a
                # session would otherwise be able to read the backup passphrase
                # and the bot token straight out of this response.
                SECRET_SETTING_KEYS = {
                    'backup_encryption_passphrase',
                    'telegram_bot_token',
                }

                settings = SystemSetting.query.all()
                result = {}
                for setting in settings:
                    is_secret = setting.key in SECRET_SETTING_KEYS
                    has_value = bool(str(setting.value or '').strip())
                    result[setting.key] = {
                        'value': '' if is_secret else setting.value,
                        'is_secret': is_secret,
                        'is_set': has_value,
                        'description': setting.description,
                        'updated_at': setting.updated_at
                    }

                os_hostname = ''
                try:
                    if hasattr(os, 'uname'):
                        os_hostname = os.uname().nodename
                except Exception:
                    os_hostname = ''

                if not os_hostname:
                    os_hostname = os.environ.get('HOSTNAME', '') or os.environ.get('COMPUTERNAME', '')

                result['os_hostname'] = {
                    'value': os_hostname,
                    'description': 'Detected OS hostname',
                    'updated_at': int(time.time())
                }

                return jsonify(result)
            except Exception as e:
                logger.error(f"Error getting system settings: {e}")
                return jsonify({'error': str(e)}), 500

        def _release_update_response(action, arguments=(), timeout=40, status_code=200):
            try:
                result = _run_privileged_helper([action, *arguments], timeout=timeout)
                return jsonify(json.loads(result.stdout)), status_code
            except Exception as error:
                # Helper errors contain only controlled diagnostics, never logs
                # or credentials. Do not expose command output wholesale.
                message = 'Update service unavailable; check status before retrying'
                try:
                    detail = json.loads(str(error))
                    if isinstance(detail, dict) and isinstance(detail.get('error'), str):
                        message = detail['error'][:250]
                except (ValueError, TypeError):
                    pass
                logger.warning('Release update operation failed: %s', action)
                return jsonify({'error': message}), 409

