        @app.route('/api/admins/create', methods=['POST'])
        @login_required
        def api_create_admin():
            try:
                role_error = _require_admin_role()
                if role_error:
                    return role_error

                data = request.json or {}
                username = str(data.get('username', '')).strip()
                password = str(data.get('password', ''))
                role = _normalize_admin_role(data.get('role', 'operator'), default_role='operator')
                email = str(data.get('email', '')).strip()

                if not username or not password:
                    return jsonify({'error': 'Username and password are required'}), 400

                if len(username) < 3 or len(username) > 32:
                    return jsonify({'error': 'Username must be between 3 and 32 characters'}), 400

                _validate_password_strength(
                    password,
                    username=username,
                    min_length=ADMIN_PASSWORD_MIN_LENGTH,
                    label='Password'
                )

                existing = Admin.query.filter_by(username=username).first()
                if existing:
                    return jsonify({'error': 'Administrator with this username already exists'}), 400

                now_ts = int(time.time())
                new_admin = Admin(
                    username=username,
                    password=bcrypt.generate_password_hash(password).decode(),
                    role=role,
                    email=email or None,
                    last_login=0,
                    login_attempts=0,
                    locked_until=0,
                    must_change_password=True,
                    created_at=now_ts,
                    updated_at=now_ts
                )

                db.session.add(new_admin)

                log_entry = LogEntry(
                    level='INFO',
                    module='auth',
                    message=(
                        f'User {current_user.username} created administrator '
                        f'{username}'
                    ),
                    timestamp=now_ts,
                    ip_address=_get_client_ip()
                )
                db.session.add(log_entry)

                db.session.commit()
                return jsonify({
                    'message': 'Administrator created successfully',
                    'id': new_admin.id
                }), 201
            except ValueError as e:
                db.session.rollback()
                return jsonify({'error': str(e)}), 400
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error creating administrator: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/admins/<int:id>/update', methods=['PUT'])
        @login_required
        def api_update_admin(id):
            try:
                role_error = _require_admin_role()
                if role_error:
                    return role_error

                admin = Admin.query.get_or_404(id)
                data = request.json or {}

                updated = False
                password_changed = False

                if 'username' in data:
                    username = str(data.get('username', '')).strip()
                    if not username:
                        return jsonify({'error': 'Username cannot be empty'}), 400
                    if len(username) < 3 or len(username) > 32:
                        return jsonify({'error': 'Username must be between 3 and 32 characters'}), 400

                    existing = Admin.query.filter(
                        Admin.username == username,
                        Admin.id != id
                    ).first()
                    if existing:
                        return jsonify({'error': 'Administrator with this username already exists'}), 400

                    admin.username = username
                    updated = True

                if 'email' in data:
                    email = str(data.get('email', '')).strip()
                    admin.email = email or None
                    updated = True

                if 'role' in data:
                    new_role = _normalize_admin_role(data.get('role'), default_role='operator')
                    first_admin = Admin.query.order_by(Admin.id.asc()).first()
                    if first_admin and admin.id == first_admin.id and new_role != 'admin':
                        return jsonify({'error': 'Built-in administrator must keep the admin role'}), 400
                    admin.role = new_role
                    updated = True

                if 'password' in data:
                    password = str(data.get('password', ''))
                    if password:
                        if 'confirm_password' in data:
                            confirm_password = str(data.get('confirm_password', ''))
                            if password != confirm_password:
                                return jsonify({'error': 'New passwords do not match'}), 400
                        _validate_password_strength(
                            password,
                            username=admin.username,
                            min_length=ADMIN_PASSWORD_MIN_LENGTH,
                            label='Password'
                        )
                        admin.set_password_hash(bcrypt.generate_password_hash(password).decode())
                        password_changed = True
                        admin.login_attempts = 0
                        admin.locked_until = 0
                        admin.must_change_password = (admin.id != current_user.id)
                        updated = True

                if not updated:
                    return jsonify({'error': 'No changes provided'}), 400

                now_ts = int(time.time())
                admin.updated_at = now_ts

                log_entry = LogEntry(
                    level='INFO',
                    module='auth',
                    message=(
                        f'User {current_user.username} updated administrator '
                        f'{admin.username}'
                    ),
                    timestamp=now_ts,
                    ip_address=_get_client_ip()
                )
                db.session.add(log_entry)

                db.session.commit()
                if password_changed and admin.id == current_user.id:
                    login_user(admin, fresh=True)

                default_admin_username = str(
                    config.get('security', {}).get('admin_default_user', '')
                ).strip()
                if admin.username == default_admin_username:
                    _remove_bootstrap_admin_password_file(username=admin.username)

                return jsonify({'message': 'Administrator updated successfully'}), 200
            except ValueError as e:
                db.session.rollback()
                return jsonify({'error': str(e)}), 400
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error updating administrator: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/admins/<int:id>/reset_password', methods=['POST'])
        @login_required
        def api_reset_admin_password(id):
            try:
                role_error = _require_admin_role()
                if role_error:
                    return role_error

                admin = Admin.query.get_or_404(id)
                data = request.json or {}
                password = str(data.get('password', ''))
                confirm_password = str(data.get('confirm_password', ''))

                if not password or not confirm_password:
                    return jsonify({'error': 'Password and confirmation are required'}), 400

                if password != confirm_password:
                    return jsonify({'error': 'Passwords do not match'}), 400

                _validate_password_strength(
                    password,
                    username=admin.username,
                    min_length=ADMIN_PASSWORD_MIN_LENGTH,
                    label='Password'
                )

                now_ts = int(time.time())
                admin.set_password_hash(bcrypt.generate_password_hash(password).decode())
                admin.login_attempts = 0
                admin.locked_until = 0
                admin.must_change_password = (admin.id != current_user.id)
                admin.updated_at = now_ts

                db.session.add(LogEntry(
                    level='WARNING',
                    module='auth',
                    message=(
                        f'User {current_user.username} reset password for administrator '
                        f'{admin.username}'
                    ),
                    timestamp=now_ts,
                    ip_address=_get_client_ip()
                ))
                db.session.commit()
                if admin.id == current_user.id:
                    login_user(admin, fresh=True)

                default_admin_username = str(
                    config.get('security', {}).get('admin_default_user', '')
                ).strip()
                if admin.username == default_admin_username:
                    _remove_bootstrap_admin_password_file(username=admin.username)

                if admin.id == current_user.id:
                    return jsonify({
                        'message': (
                            f'Password reset for {admin.username}. '
                            'Your current session remains active.'
                        )
                    }), 200

                return jsonify({
                    'message': f'Password reset for {admin.username}. The user must change it at next login.'
                }), 200
            except ValueError as e:
                db.session.rollback()
                return jsonify({'error': str(e)}), 400
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error resetting administrator password: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/user/change_password', methods=['POST'])
        @login_required
        def api_change_password():
            try:
                data = request.json or {}
                current_password = data.get('current_password', '')
                new_password = data.get('new_password', '')
                confirm_password = data.get('confirm_password', '')

                if not current_password or not new_password or not confirm_password:
                    return jsonify({'error': 'Missing required fields'}), 400

                if new_password != confirm_password:
                    return jsonify({'error': 'New passwords do not match'}), 400

                _validate_password_strength(
                    new_password,
                    username=current_user.username,
                    min_length=ADMIN_PASSWORD_MIN_LENGTH,
                    label='New password'
                )

                admin = Admin.query.get(current_user.id)
                if not admin:
                    return jsonify({'error': 'Current user not found'}), 404

                if not bcrypt.check_password_hash(admin.password, current_password):
                    return jsonify({'error': 'Current password is incorrect'}), 400

                if bcrypt.check_password_hash(admin.password, new_password):
                    return jsonify({'error': 'New password must be different from current password'}), 400

                admin.set_password_hash(bcrypt.generate_password_hash(new_password).decode())
                admin.updated_at = int(time.time())
                admin.login_attempts = 0
                admin.locked_until = 0
                admin.must_change_password = False

                log_entry = LogEntry(
                    level='INFO',
                    module='auth',
                    message=f'User {admin.username} changed password',
                    timestamp=int(time.time()),
                    ip_address=_get_client_ip()
                )
                db.session.add(log_entry)
                db.session.commit()
                if admin.id == current_user.id:
                    login_user(admin, fresh=True)

                default_admin_username = str(
                    config.get('security', {}).get('admin_default_user', '')
                ).strip()
                if admin.username == default_admin_username:
                    _remove_bootstrap_admin_password_file(username=admin.username)

                return jsonify({'message': 'Password changed successfully'}), 200

            except ValueError as e:
                db.session.rollback()
                return jsonify({'error': str(e)}), 400
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error changing password: {e}")
                return jsonify({'error': str(e)}), 500
        
        def _database_health():
            try:
                db.session.execute(text('SELECT id FROM admin LIMIT 1')).scalar()
                return {'status': 'ok', 'message': 'Database responds to a read query'}
            except Exception:
                db.session.rollback()
                return {'status': 'error', 'message': 'Database is unavailable'}

        def _receiver_health(station, connection, stats, now):
            connected = bool(connection.get('connected'))
            stamp = float(stats.get('last_frame_at', 0) or 0)
            age = max(0.0, now - stamp) if stamp > 0 else None
            if not connected:
                stream_status, message = 'unavailable', 'Receiver is disconnected'
            elif age is None:
                stream_status, message = 'waiting', 'No valid RTCM frame received yet'
            elif age > 30:
                stream_status, message = 'stale', 'No valid RTCM frame in the last 30 seconds'
            else:
                stream_status, message = 'ok', 'Valid RTCM frames are arriving'
            return {
                'id': station.id, 'name': station.name,
                'receiver': 'ok' if connected else 'disconnected',
                'rtcm': stream_status, 'message': message,
                'last_frame_age_seconds': round(age, 1) if age is not None else None,
                'frames_parsed': int(stats.get('frames_parsed', 0) or 0),
                'crc_failures': int(stats.get('crc_failures', 0) or 0),
            }

        @app.route('/api/health')
        def api_health():
            # Liveness/readiness only. An unplugged receiver must not cause
            # watchdog restart loops; detailed hardware state requires login.
            database = _database_health()
            healthy = database['status'] == 'ok'
            return jsonify({
                'status': 'healthy' if healthy else 'unhealthy',
                'timestamp': int(time.time()), 'version': __version__,
                'components': {'web': {'status': 'ok'}, 'database': database},
            }), 200 if healthy else 503

        @app.route('/api/diagnostics')
        @login_required
        def api_diagnostics():
            from app.bluetooth.core import bluetooth_manager
            from app.ntrip.core import ntrip_server
            from app.rtcm.stream import stream_manager
            database = _database_health()
            components = {'web': {'status': 'ok', 'message': 'Web application responds'},
                          'database': database}
            stations = []
            try:
                running = bool(ntrip_server.running)
                components['ntrip'] = {'status': 'ok' if running else 'error',
                                       'message': 'NTRIP server is running' if running else 'NTRIP server is stopped'}
                if database['status'] != 'ok':
                    raise RuntimeError('database unavailable')
                configured = BaseStation.query.order_by(BaseStation.id.asc()).all()
                # Copy in-memory state only; no Bluetooth scan or RSSI command.
                with bluetooth_manager.lock:
                    connections = {key: dict(value) for key, value in bluetooth_manager.connections.items()}
                    recovery = dict(getattr(bluetooth_manager, '_adapter_recovery_state', {}))
                now = time.monotonic()
                stations = [_receiver_health(station, connections.get(str(station.id), {}),
                                             stream_manager.get_stats(station.id), now)
                            for station in configured]
                components['receivers'] = {
                    'status': ('not_configured' if not stations else
                               'ok' if all(row['receiver'] == 'ok' for row in stations) else 'warning'),
                    'message': f"{sum(row['receiver'] == 'ok' for row in stations)}/{len(stations)} receivers connected",
                }
                if recovery.get('status') in ('resetting', 'waiting_for_connection', 'failed'):
                    components['receivers']['message'] += (
                        f"; Bluetooth recovery: {recovery['status']} (attempt {recovery.get('attempt', 0)})")
                components['receivers']['recovery'] = recovery
                components['rtcm'] = {
                    'status': ('not_configured' if not stations else
                               'ok' if all(row['rtcm'] == 'ok' for row in stations) else 'warning'),
                    'message': f"{sum(row['rtcm'] == 'ok' for row in stations)}/{len(stations)} receivers provide fresh RTCM",
                }
            except Exception:
                components.setdefault('ntrip', {'status': 'unknown', 'message': 'NTRIP status unavailable'})
                components['receivers'] = {'status': 'unknown', 'message': 'Receiver status unavailable'}
                components['rtcm'] = {'status': 'unknown', 'message': 'RTCM status unavailable'}
            degraded = any(item['status'] in ('warning', 'error', 'unknown') for item in components.values())
            return jsonify({'status': 'degraded' if degraded else 'healthy',
                            'timestamp': int(time.time()), 'version': __version__,
                            'components': components, 'stations': stations,
                            'rtcm_stale_after_seconds': 30})

        @app.route('/sourcetable.txt')
        @app.route('/sourcetable')
        def http_sourcetable():
            """Public NTRIP sourcetable over HTTP (Fix #16).

            Public NTRIP caster aggregators (rtk2go, centipede, etc.) and many
            monitoring tools fetch the sourcetable over plain HTTP rather than
            speaking the NTRIP protocol on port 2101. This mirrors the
            SOURCETABLE the NTRIP server emits, in the standard STR/CAS format.

            No authentication: a sourcetable is public discovery data by design.
            """
            try:
                def _s(key, default=''):
                    row = SystemSetting.query.filter_by(key=key).first()
                    return (row.value if row and row.value is not None else default)

                caster_id = _s('caster_identifier', 'GNSS-Caster')
                caster_op = _s('caster_operator', 'Unknown')
                caster_country = _s('caster_country', 'RUS')
                caster_lat = _s('caster_lat', '0.00')
                caster_lon = _s('caster_lon', '0.00')
                caster_host = _s('caster_host', request.host.split(':')[0])
                try:
                    ntrip_port = int(_s('ntrip_port', '2101') or 2101)
                except (TypeError, ValueError):
                    ntrip_port = 2101

                lines_out = [
                    (
                        f"CAS;{caster_host};{ntrip_port};{caster_id};{caster_op};0;"
                        f"{caster_country};{caster_lat};{caster_lon};0;0;"
                        f"http://{caster_host}/sourcetable.txt"
                    ),
                ]

                for mp in MountPoint.query.filter_by(is_active=True).all():
                    lat, lon = '0.00', '0.00'
                    try:
                        base = mp.base_station
                        if base and getattr(base, 'manual_lat', None):
                            lat = f"{float(base.manual_lat):.4f}"
                            lon = f"{float(base.manual_lon):.4f}"
                    except Exception:
                        pass
                    generator = (mp.description or 'GNSS-Caster').replace(';', ' ')
                    lines_out.append(
                        f"STR;{mp.name};{mp.name};RTCM 3.2;;2;"
                        f"GPS+GLO+GAL+BDS;;{caster_country};"
                        f"{lat};{lon};0;1;{generator};none;B;N;9600;"
                    )

                lines_out.append("ENDSOURCETABLE")
                body = "\r\n".join(lines_out) + "\r\n"
                return Response(body, mimetype='text/plain')
            except Exception as e:
                logger.error(f"Error building HTTP sourcetable: {e}")
                return Response(
                    "ENDSOURCETABLE\r\n", mimetype='text/plain', status=500
                )
        
